INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_coremath_s1_016', 'topic_wcoremath_quadratic', 'subj_wassce_core_math', 'exam_wassce', NULL, NULL, 'The equation x² + kx + 9 = 0 has equal roots. Find the positive value of k.', 'multiple_choice', NULL, '["A. 3","B. 9","C. 36","D. 6"]', 'D', 'Equal roots require the discriminant to be zero: k² − 4(1)(9) = 0, so k² = 36 and k = ±6. The positive value is k = 6. Therefore the correct answer is D: 6.', 'hard', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Find', 'AO3', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_coremath_s1_017', 'topic_wcoremath_geometry', 'subj_wassce_core_math', 'exam_wassce', NULL, NULL, 'What is the sum of the interior angles of a triangle?', 'multiple_choice', NULL, '["A. 180°","B. 90°","C. 270°","D. 360°"]', 'A', 'The three interior angles of any triangle add up to 180°; 360° is the total for a quadrilateral. Therefore the correct answer is A: 180°.', 'easy', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'State', 'AO1', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_coremath_s1_018', 'topic_wcoremath_geometry', 'subj_wassce_core_math', 'exam_wassce', NULL, NULL, 'Two angles lie on a straight line. If one of them is 65°, find the other angle.', 'multiple_choice', NULL, '["A. 25°","B. 115°","C. 65°","D. 125°"]', 'B', 'Angles on a straight line are supplementary (they add to 180°), so the other angle is 180° − 65° = 115°. Therefore the correct answer is B: 115°.', 'easy', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Find', 'AO1', NULL, NULL, 'board_waec');
