INSERT INTO _migration_405_guard(valid) SELECT CASE WHEN (SELECT COUNT(*) FROM questions WHERE id IN ('q_was_coremath_s1_013', 'q_was_coremath_s1_014', 'q_was_coremath_s1_015', 'q_was_coremath_s1_016', 'q_was_coremath_s1_017', 'q_was_coremath_s1_018')) = 6 AND (SELECT COUNT(*) FROM question_content_releases r WHERE r.question_id IN ('q_was_coremath_s1_013', 'q_was_coremath_s1_014', 'q_was_coremath_s1_015', 'q_was_coremath_s1_016', 'q_was_coremath_s1_017', 'q_was_coremath_s1_018') AND r.batch_id IS 'wassce-core-math-sprint1-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1) = 6 THEN 1 ELSE 0 END;
